INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16193$nota-0267$m16193$, $m16194$Exercise Physiology McArdle.pdf$m16194$, $m16195$638$m16195$, $m16196$Mild hypothermia 35.0°C: Maximal shivering, increased blood pressure. 34.0°C: Amnesia; dysarthria; poor judgment; behavior change. Moderate hypothermia 32.0°C: Stupor. 30.0°C: Cardiac arrhythmias; decreased cardiac output. Severe hypothermia 28.0°C: Ventricular fibrillation likely; hypoventilation... 13.7°C: Lowest adult survival from accidental hypothermia.$m16196$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16197$nota-0267$m16197$, $m16198$nota-0261$m16198$, $m16199$complementa$m16199$, $m16200$nota-0261 traz o continuum equivalente para doenças por calor; esta nota traz o continuum análogo para o extremo oposto (frio)$m16200$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16201$nota-0267$m16201$, $m16202$nota-0270$m16202$, $m16203$complementa$m16203$, $m16204$roupa molhada (nota-0270), citada no corpo da nota como fator agravante de risco de hipotermia — link estrutural ausente até auditoria de 2026-08-02$m16204$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16205$nota-0270$m16205$, $m16206$Exercise Physiology McArdle.pdf$m16206$, $m16207$623$m16207$, $m16208$When clothing becomes wet, through either external moisture or condensation from sweating, it loses almost 90% of its insulating properties. This facilitates heat loss from the body because water conducts heat 25 times faster than air.$m16208$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16209$nota-0270$m16209$, $m16210$nota-0267$m16210$, $m16211$complementa$m16211$, $m16212$roupa molhada é um fator de risco direto para a progressão de hipotermia descrita na tabela de estágios da nota-0267$m16212$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16213$nota-0270$m16213$, $m16214$nota-0269$m16214$, $m16215$complementa$m16215$, $m16216$contrasta com a nota-0269: mesmo com geração de calor metabólico ativa, roupa molhada acelera muito a perda de calor e pode superar a produção metabólica$m16216$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16217$nota-0270$m16217$, $m16218$nota-0266$m16218$, $m16219$complementa$m16219$, $m16220$vento relativo/wind-chill (nota-0266), citado no corpo da nota como um dos três fatores combinados de maior risco de hipotermia em descidas após subidas suadas — link estrutural ausente até auditoria de 2026-08-02$m16220$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16221$nota-0271$m16221$, $m16222$Exercise Physiology McArdle.pdf$m16222$, $m16223$638$m16223$, $m16224$Successful ocean swimmers possess a larger amount of subcutaneous fat than highly trained non–ocean swimmers. The additional fat increases the effective insulation in cold water when peripheral blood diverts from the body's shell to the core.$m16224$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16225$nota-0271$m16225$, $m16226$Exercise Physiology McArdle.pdf$m16226$, $m16227$638$m16227$, $m16228$A person with excess body fat who rests comfortably immersed to the neck in 26°C (78.8°F) water may sweat about the forehead during vigorous physical activity. For this person, 18°C (64.4°F) provides a more favorable water temperature for high-intensity effort. For a lean person, water at 18°C (64.4°F) proves debilitating during rest and activity.$m16228$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16229$nota-0271$m16229$, $m16230$nota-0262$m16230$, $m16231$complementa$m16231$, $m16232$contraste direto: a mesma gordura corporal que prejudica a tolerância ao calor (nota-0262) beneficia a tolerância ao frio — efeito oposto dependendo do ambiente$m16232$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16233$nota-0274$m16233$, $m16234$Exercise Physiology McArdle.pdf$m16234$, $m16235$604$m16235$, $m16236$Climbers should spend several nights at 2500 to 3000 m (8200 to 9800 ft) before going higher, and an extra night should be added for each additional 600 to 900 m (1968 to 2952 ft) climbed. Abrupt increases of more than 600 m in the altitude for sleeping should be avoided at 2500 m (8202 ft) or above (\"climb high–sleep low\").$m16236$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16237$nota-0274$m16237$, $m16238$Exercise Physiology McArdle.pdf$m16238$, $m16239$605$m16239$, $m16240$Prevention 1. Slow ascent for susceptible individuals (average increase in sleeping altitude of 300 to 350 m·d−1 (984 to 1148 ft·d−1) above 2500 m (8200 ft)).$m16240$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16241$nota-0274$m16241$, $m16242$Exercise Physiology McArdle.pdf$m16242$, $m16243$604$m16243$, $m16244$Rapid ascent to 4200 m almost guarantees some form of AMS.$m16244$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16245$nota-0274$m16245$, $m16246$nota-0134$m16246$, $m16247$complementa$m16247$, $m16248$protocolo prático de segurança para exposição a altitude, ausente na nota-0134$m16248$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16249$nota-0274$m16249$, $m16250$nota-0273$m16250$, $m16251$complementa$m16251$, $m16252$esta nota é o protocolo de segurança específico contra mal agudo da montanha, dentro do cronograma geral de aclimatização da nota-0273$m16252$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16253$nota-0281$m16253$, $m16254$Exercise Physiology McArdle.pdf$m16254$, $m16255$762$m16255$, $m16256$The following equation computes a goal body weight based on a desired percentage body fat level: Goal body weight = Fat-free body mass ÷ (1.00 - desired %fat)$m16256$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m16257$nota-0281$m16257$, $m16258$Exercise Physiology McArdle.pdf$m16258$, $m16259$763$m16259$, $m16260$Suppose a 91-kg (200-lb) man, currently with 20% body fat, wants to know how much fat weight to lose to attain a body fat composition of 10%... Goal body weight = 72.8 kg ÷ (1.00 - 0.10) = 80.9 kg (178 lb). Goal fat loss = 91 kg - 80.9 kg = 10.1 kg (22.2 lb).$m16260$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m16261$nota-0281$m16261$, $m16262$nota-0033$m16262$, $m16263$complementa$m16263$, $m16264$fornece um método para estimar um peso-meta específico a partir de %gordura desejado, complementando a discussão de razão potência/peso da nota-0033$m16264$)
